def check_coloring(N, coloring_func):
    # 1. Generate the grid
    grid = {}
    unique_colors = set()
    for i in range(N):
        for j in range(N):
            color = coloring_func(i, j)
            grid[(i, j)] = color
            unique_colors.add(color)

    # 2. Check the local constraint for all 2x2 squares
    # The constraint: in each 2x2 square, at least two squares have the same color.
    # Equivalently: the number of unique colors in any 2x2 square must be <= 3.
    constraint_satisfied = True
    for i in range(N - 1):
        for j in range(N - 1):
            colors_in_2x2 = {grid[(i, j)], grid[(i+1, j)], grid[(i, j+1)], grid[(i+1, j+1)]}
            num_unique = len(colors_in_2x2)
            if num_unique == 4:
                constraint_satisfied = False
                # Print a detailed message if the constraint fails for debugging
                print(f"Constraint failed at ({i}, {j}): Colors are {colors_in_2x2}")
                break
        if not constraint_satisfied:
            break

    if constraint_satisfied:
        print("Local constraint satisfied.")
    else:
        print("Local constraint FAILED.")

    # 3. Output the number of unique colors used
    num_unique_colors = len(unique_colors)
    print(f"Number of unique colors used: {num_unique_colors}")
    return num_unique_colors

# Coloring function C(i, j) = i + j
def coloring_ij(i, j):
    return i + j

N = 5
check_coloring(N, coloring_ij)

